contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(uint256 drugs, uint256 eth) public {
        require(address(this).balance >= eth);
        c.seedMarket(drugs);
        bool ok;
        try c.buyDrugs{value: eth}() { ok = true; } catch { ok = false; }
        assert(ok);
    }
    receive() external payable {}
    fallback() external payable {}
}

