        require(!c.initialized());
        c.seedMarket(drugs);
        assert(c.initialized());
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test() public {
        address before = c.ceoAddress();
        require(before != address(this));
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.DrugDealer.selector));
        assert(c.ceoAddress() == before);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(address caller, address ceoBefore) public {
        require(caller != ceoBefore, "caller must not be CEO");
        require(c.ceoAddress() == ceoBefore, "ceoBefore must match actual ceo");

        bool reverted;
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(c.DrugDealer.selector)
        );
        // simulate caller: test runs as msg.sender; use this contract as caller
        require(msg.sender != address(this), "sanity");
        reverted = !ok;

        assert(reverted);
    }

    receive() external payable {}
    fallback() external payable {}
}
